sys_ui_action.script:
function confirmDeleteSelectedWorkloads() {
    var checkedSysIds = g_list.getChecked();

    if (!checkedSysIds) {
        var gm = new GlideModal('', false, 500);
        gm.setTitle('No workloads selected');

        top.window.deleteSelectedWorkloadsCallback = function() {
            gm.destroy();
            return false;
        };

        var noSelectionHtml =
            '<div style="padding: 8px 4px 4px 4px; font-size: 16px; line-height: 1.5;">' +
                '<p>No workloads selected. Please select one or more workloads from the list.</p>' +
                '<div style="display:flex; justify-content:flex-end; margin-top:20px;">' +
                    '<button style="width: 100%" class="btn btn-default" onclick="top.window.deleteSelectedWorkloadsCallback(); return false;">OK</button>' +
                '</div>' +
            '</div>';

        gm.renderWithContent(noSelectionHtml);
        return false;
    }

    var count = checkedSysIds.split(',').length;

    var gm = new GlideModal('', false, 700);
    gm.setTitle('Confirm selected workload deletion');

    top.window.deleteSelectedWorkloadsCallback = function(answer) {
        gm.destroy();

        if (answer === 'yes') {
            var ga = new GlideAjax('IllumioDeletionHandler');
            ga.addParam('sysparm_name', 'deleteSelectedWorkloads');
            ga.addParam('sysparm_checked_sysids', checkedSysIds);
            ga.getXMLAnswer(function(response) {
                var result = JSON.parse(response);
                if (result.success) {
                    g_list.refresh();
                    var msgContainer = top.document.getElementById('output_messages') ||
                        top.document.getElementById('page_notifications');
                    if (msgContainer) {
                        msgContainer.innerHTML = '<div class="outputmsg_success"><span class="outputmsg_text">' + result.message + '</span></div>';
                    }
                } else {
                    var errContainer = top.document.getElementById('output_messages') ||
                        top.document.getElementById('page_notifications');
                    if (errContainer) {
                        errContainer.innerHTML = '<div class="outputmsg_error"><span class="outputmsg_text">' + result.message + '</span></div>';
                    }
                }
            });
        }

        return false;
    };

    var html =
        '<div style="padding: 8px 4px 4px 4px; font-size: 16px; line-height: 1.5;">' +
            '<p>You are about to delete <b>' + count + '</b> selected workload(s) from PCE.</p>' +
            '<ul style="margin: 10px 0;">' +
                '<li><b>Managed</b> workloads (with VEN) will be <b>unpaired</b> from PCE.</li>' +
                '<li><b>Unmanaged</b> workloads will be <b>deleted</b> from PCE.</li>' +
                '<li>Workloads not known to PCE or missing href will be skipped.</li>' +
            '</ul>' +
            '<p>It is strongly recommended to run the following in order before proceeding:<br>' +
            '1. Data Collection - To discover the latest state workloads.<br>' +
            '2. Preview workload deletion - To verify all workloads.</p>' +
            '<p><b>Deletion is a non-reversible action.</b> Click "Yes" to proceed.</p>' +
            '<div style="display:flex; justify-content:flex-end; gap:12px; margin-top:20px;">' +
                '<button style="flex: 1; width: 100%" class="btn btn-default" onclick="top.window.deleteSelectedWorkloadsCallback(\'no\'); return false;">Cancel</button>' +
                '<button style="flex: 1; width: 100%" class="btn btn-danger" onclick="top.window.deleteSelectedWorkloadsCallback(\'yes\'); return false;">Yes</button>' +
            '</div>' +
        '</div>';

    gm.renderWithContent(html);
    return false;
}
